"""Card capture and refunds.

Charge failures in some code paths are documented as failing closed with HTTP
500. Restoring warehouse stock after a refund is inventory's job, not this
module's ledger.
"""

_CHARGES: list[dict] = []


def charge(user_id: int, amount: float, items: list[dict]) -> dict:
    rec = {
        "user_id": user_id,
        "amount": amount,
        "items": items,
        "status": "captured",
    }
    _CHARGES.append(rec)
    return rec


def refund(order: dict) -> dict:
    """Mark a capture as refunded. Does not touch warehouse stock."""
    return {"refunded": True, "amount": order.get("total", 0)}


def fail_closed_message() -> str:
    """Red herring for searches about crashes / HTTP 500."""
    return "charge failures should fail closed with HTTP 500"


def reset_store() -> None:
    _CHARGES.clear()

"""Warehouse stock and bin allocation."""

from fastapi import HTTPException

_DEFAULT_STOCK: dict[str, int] = {
    "widget": 3,
    "gadget": 10,
}

_STOCK: dict[str, int] = dict(_DEFAULT_STOCK)

WAREHOUSE_BINS = {
    "widget": {"aisle": "A1", "slots": [0, 1, 2]},
    "gadget": {"aisle": "B2", "slots": list(range(10))},
}


def get_stock(sku: str) -> int:
    return int(_STOCK.get(sku, 0))


def reserve(sku: str, qty: int) -> None:
    """Take ``qty`` units of ``sku`` or raise HTTP 409."""
    available = get_stock(sku)
    if qty > available:
        raise HTTPException(status_code=409, detail="out of stock")
    _STOCK[sku] = available - qty


def release(sku: str, qty: int) -> None:
    _STOCK[sku] = get_stock(sku) + qty


def allocate_bin(items: list[dict]) -> str:
    """Pick a warehouse aisle for the line items and decrement stock."""
    last_aisle = "A1"
    for item in items:
        sku = item.get("sku") or "widget"
        qty = int(item.get("qty", 1))
        bins = WAREHOUSE_BINS[sku]
        last_aisle = bins["aisle"]
        _ = bins["slots"][qty - 1]
        _STOCK[sku] = get_stock(sku) - qty
    return last_aisle


def reset_store() -> None:
    """Test helper — restore seeded stock."""
    _STOCK.clear()
    _STOCK.update(_DEFAULT_STOCK)

"""Signed outbound callbacks for third-party endpoints."""

from __future__ import annotations

import hashlib
import hmac
import json

from app import settings


class Endpoint:
    def __init__(self, url: str, secret: str, active: bool = True) -> None:
        self.url = url
        self.secret = secret
        self.active = active

    def disable(self) -> None:
        self.active = False

    def enable(self) -> None:
        self.active = True


_ENDPOINTS: list[Endpoint] = [
    Endpoint("https://hooks.example.invalid/shop", "dev-hook-secret"),
]
_DELIVERIES: list[dict] = []


def sign_payload(secret: str, body: str) -> str:
    digest = hmac.new(secret.encode("utf-8"), body.encode("utf-8"), hashlib.sha256)
    return digest.hexdigest()


def encode_body(payload: dict) -> str:
    return json.dumps(payload, sort_keys=True)


def active_endpoints() -> list[Endpoint]:
    return [item for item in _ENDPOINTS if item.active]


def register_endpoint(url: str, secret: str) -> Endpoint:
    item = Endpoint(url, secret)
    _ENDPOINTS.append(item)
    return item


def queue_delivery(kind: str, payload: dict) -> list[dict]:
    if not settings.webhooks_enabled():
        return []
    body = encode_body(payload)
    sent: list[dict] = []
    for endpoint in active_endpoints():
        rec = {
            "url": endpoint.url,
            "kind": kind,
            "signature": sign_payload(endpoint.secret, body),
        }
        _DELIVERIES.append(rec)
        sent.append(rec)
    return sent


def deliveries() -> list[dict]:
    return list(_DELIVERIES)


def last_delivery() -> dict | None:
    if not _DELIVERIES:
        return None
    return _DELIVERIES[-1]


def reset_store() -> None:
    _DELIVERIES.clear()
    for item in _ENDPOINTS:
        item.enable()

"""Aggregated storefront totals for staff dashboards."""

from __future__ import annotations

from app import orders, pricing, settings, tax


class Snapshot:
    def __init__(self, merchandise: float, count: int) -> None:
        self.merchandise = merchandise
        self.count = count

    def as_dict(self) -> dict:
        return {"merchandise": self.merchandise, "count": self.count}

    def empty(self) -> bool:
        return self.count == 0


def iter_counted_rows() -> list[dict]:
    return list(orders.list_orders())


def line_amount(item: dict) -> float:
    return float(item.get("price") or 0.0)


def quoted_line(item: dict) -> float:
    return pricing.quote_price(
        str(item.get("sku") or "widget"),
        int(item.get("qty", 1) or 1),
        float(item.get("price") or 0.0),
    )


def merchandise_total(rows: list[dict]) -> float:
    amount = 0.0
    for row in rows:
        for item in row.get("items") or []:
            amount += line_amount(item)
    return round(amount, 2)


def counted_rows() -> list[dict]:
    return iter_counted_rows()


def build_snapshot() -> dict:
    rows = counted_rows()
    merchandise = merchandise_total(rows)
    if settings.flag_enabled("include_tax_in_reports"):
        merchandise = tax.inclusive_total(merchandise)
    snap = Snapshot(merchandise, len(rows))
    return snap.as_dict()


def order_count() -> int:
    return len(counted_rows())


def average_ticket() -> float:
    rows = counted_rows()
    if not rows:
        return 0.0
    return round(merchandise_total(rows) / len(rows), 2)


def sku_units(sku: str) -> int:
    total = 0
    for row in counted_rows():
        for item in row.get("items") or []:
            if str(item.get("sku") or "") == sku:
                total += int(item.get("qty", 1) or 1)
    return total


def reset_store() -> None:
    return None

