class FeatureFlag:
    def __init__(self, name: str, enabled: bool = False) -> None:
        self.name = name
        self.enabled = enabled

    def enable(self) -> None:
        self.enabled = True

    def disable(self) -> None:
        self.enabled = False

    def is_on(self) -> bool:
        return bool(self.enabled)


_FLAGS: dict[str, FeatureFlag] = {
    "include_tax_in_reports": FeatureFlag("include_tax_in_reports", False),
    "signed_webhooks": FeatureFlag("signed_webhooks", True),
    "quiet_hours": FeatureFlag("quiet_hours", False),
}


def get_setting(key: str, default: object | None = None) -> object:
    if key in _OVERRIDES:
        return _OVERRIDES[key]
    if key in _DEFAULTS:
        return _DEFAULTS[key]
    return default


def set_setting(key: str, value: object) -> None:
    _OVERRIDES[key] = value


def clear_override(key: str) -> None:
    _OVERRIDES.pop(key, None)


def timezone() -> str:
    return str(get_setting("timezone", "UTC"))


def currency() -> str:
    return str(get_setting("currency", "USD"))


def tax_rate() -> float:
    return float(get_setting("tax_rate", 0.0) or 0.0)


def mail_from() -> str:
    return str(get_setting("mail_from", "receipts@example.com"))


def default_zone() -> str:
    return str(get_setting("default_zone", "domestic"))


def loyalty_enabled() -> bool:
    return bool(get_setting("loyalty_enabled", True))


def webhooks_enabled() -> bool:
    return bool(get_setting("webhooks_enabled", False))


def flag(name: str) -> FeatureFlag:
    if name not in _FLAGS:
        _FLAGS[name] = FeatureFlag(name, False)
    return _FLAGS[name]


def flag_enabled(name: str) -> bool:
    return flag(name).is_on()


def enable_flag(name: str) -> None:
    flag(name).enable()


def disable_flag(name: str) -> None:
    flag(name).disable()


def snapshot() -> dict[str, object]:
    data = dict(_DEFAULTS)
    data.update(_OVERRIDES)
    data["flags"] = {name: item.is_on() for name, item in _FLAGS.items()}
    return data


def reset_store() -> None:
    _OVERRIDES.clear()
    for item in _FLAGS.values():
        item.disable()
    _FLAGS["signed_webhooks"].enable()

"""Sales-tax tables keyed by shop settings."""

from __future__ import annotations

from app import settings


class Nexus:
    def __init__(self, code: str, rate: float) -> None:
        self.code = code
        self.rate = rate

    def applies(self, code: str) -> bool:
        return self.code == code

    def amount(self, subtotal: float) -> float:
        return round(float(subtotal) * float(self.rate), 2)


_NEXUS: dict[str, Nexus] = {
    "home": Nexus("home", 0.0),
    "remote": Nexus("remote", 0.0),
}


def home_nexus() -> Nexus:
    return _NEXUS["home"]


def remote_nexus() -> Nexus:
    return _NEXUS["remote"]


def rate_for(code: str = "home") -> float:
    nexus = _NEXUS.get(code) or home_nexus()
    if nexus.rate:
        return nexus.rate
    return settings.tax_rate()


def tax_on(subtotal: float, code: str = "home") -> float:
    return round(float(subtotal) * rate_for(code), 2)


def away_levy(subtotal: float) -> float:
    return tax_on(subtotal, "remote")


def inclusive_total(subtotal: float, code: str = "home") -> float:
    return round(float(subtotal) + tax_on(subtotal, code), 2)


def exempt(subtotal: float) -> float:
    return round(float(subtotal), 2)


def set_nexus_rate(code: str, rate: float) -> None:
    if code not in _NEXUS:
        _NEXUS[code] = Nexus(code, rate)
    else:
        _NEXUS[code].rate = rate


def nexus_codes() -> list[str]:
    return sorted(_NEXUS)


def reset_store() -> None:
    _NEXUS.clear()
    _NEXUS["home"] = Nexus("home", 0.0)
    _NEXUS["remote"] = Nexus("remote", 0.0)

"""Append-only activity stream for storefront operations."""

from __future__ import annotations

KIND_SALE = "sale"
KIND_CANCEL = "cancellation"


class ActivityEvent:
    def __init__(self, kind: str, actor_id: int, order_id: int, **extra: object) -> None:
        self.kind = kind
        self.actor_id = actor_id
        self.order_id = order_id
        self.extra = extra

    def as_dict(self) -> dict:
        payload = {
            "kind": self.kind,
            "actor_id": self.actor_id,
            "order_id": self.order_id,
        }
        payload.update(self.extra)
        return payload

    def is_open_sale(self) -> bool:
        return self.kind == KIND_SALE


_EVENTS: list[ActivityEvent] = []


def append_event(kind: str, actor_id: int, order_id: int, **extra: object) -> dict:
    event = ActivityEvent(kind, actor_id, order_id, **extra)
    _EVENTS.append(event)
    return event.as_dict()


def record_sale(actor_id: int, order_id: int, total: float) -> dict:
    return append_event(KIND_SALE, actor_id, order_id, total=float(total))


def record_cancellation(actor_id: int, order_id: int) -> dict:
    return append_event(KIND_CANCEL, actor_id, order_id)


def events_for_order(order_id: int) -> list[dict]:
    return [event.as_dict() for event in _EVENTS if event.order_id == order_id]


def events_for_actor(actor_id: int) -> list[dict]:
    return [event.as_dict() for event in _EVENTS if event.actor_id == actor_id]


def latest_for_order(order_id: int) -> dict | None:
    matches = events_for_order(order_id)
    if not matches:
        return None
    return matches[-1]


def open_sales() -> list[dict]:
    latest: dict[int, ActivityEvent] = {}
    for event in _EVENTS:
        latest[event.order_id] = event
    return [event.as_dict() for event in latest.values() if event.is_open_sale()]


def count() -> int:
    return len(_EVENTS)


def reset_store() -> None:
    _EVENTS.clear()

"""Outbound messages and a process-local inbox."""

from __future__ import annotations

from app import settings


class Message:
    def __init__(self, user_id: int, to: str, template: str, ref: str) -> None:
        self.user_id = user_id
        self.to = to
        self.template = template
        self.ref = ref

    def as_dict(self) -> dict:
        return {
            "user_id": self.user_id,
            "to": self.to,
            "template": self.template,
            "ref": self.ref,
            "from": settings.mail_from(),
        }


_CONTACTS: dict[int, str] = {}
_INBOX: list[Message] = []


def capture_contact(user_id: int, email: str) -> None:
    _CONTACTS[user_id] = email


def contact_for(user_id: int) -> str | None:
    return _CONTACTS.get(user_id)


def dispatch_receipt(user_id: int, order_id: int) -> dict:
    if hours_notice():
        return {
            "user_id": user_id,
            "to": contact_for(user_id) or "",
            "template": "receipt",
            "ref": f"order:{order_id}",
            "from": settings.mail_from(),
            "skipped": True,
        }
    to = contact_for(user_id) or ""
    message = Message(user_id, to, "receipt", f"order:{order_id}")
    _INBOX.append(message)
    return message.as_dict()


def dispatch_notice(user_id: int, template: str, ref: str) -> dict:
    to = contact_for(user_id) or ""
    message = Message(user_id, to, template, ref)
    _INBOX.append(message)
    return message.as_dict()


def list_messages(user_id: int | None = None) -> list[dict]:
    rows = _INBOX if user_id is None else [item for item in _INBOX if item.user_id == user_id]
    return [item.as_dict() for item in rows]


def last_message(user_id: int | None = None) -> dict | None:
    rows = list_messages(user_id)
    if not rows:
        return None
    return rows[-1]


def has_contact(user_id: int) -> bool:
    return user_id in _CONTACTS


def hours_notice() -> bool:
    return settings.flag_enabled("quiet_hours")


def drop_contact(user_id: int) -> None:
    _CONTACTS.pop(user_id, None)


def reset_store() -> None:
    _CONTACTS.clear()
    _INBOX.clear()
